import { readFileSync, statSync } from 'node:fs';
import { defaultAlias, isAlias } from '../store/db.js';

/**
 * ADR-003: the list of every mailbox on the mail server, generated by root
 * (`doveadm user '*'`) into a file the connector can read. One login per line,
 * optionally followed by whitespace and an alias override; `#` starts a comment.
 */
export interface DirectoryEntry {
  /** IMAP/SMTP login as the mail server knows it (contact@brand.tld). */
  login: string;
  /** Address shown to users and used as From; same as login on virtual-mailbox setups. */
  email: string;
  /** Short name said in chat (brand of the domain; `<brand>-<localpart>` for non-contact@ logins). */
  alias: string;
}

/** Deterministic alias for a server mailbox: contact@brand.tld → brand, billing@brand.tld → brand-billing. */
export function directoryAlias(login: string): string {
  const addr = login.trim().toLowerCase();
  const at = addr.lastIndexOf('@');
  const brand = defaultAlias(addr, null);
  if (at <= 0) return brand;
  const local = addr.slice(0, at).replace(/[^a-z0-9_-]+/g, '-').replace(/^[-_]+|[-_]+$/g, '');
  if (local === 'contact' || local === '' || brand === 'mailbox') return brand;
  const combined = `${brand}-${local}`.slice(0, 32).replace(/-+$/, '');
  return isAlias(combined) ? combined : brand;
}

export function parseDirectory(text: string): DirectoryEntry[] {
  const out: DirectoryEntry[] = [];
  const seenLogin = new Set<string>();
  const seenAlias = new Set<string>();
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.replace(/#.*$/, '').trim();
    if (!line) continue;
    const [loginRaw, aliasRaw] = line.split(/\s+/);
    const login = (loginRaw ?? '').toLowerCase();
    if (!login || login.length > 320 || seenLogin.has(login)) continue;
    const wanted = aliasRaw && isAlias(aliasRaw.toLowerCase()) ? aliasRaw.toLowerCase() : directoryAlias(login);
    let alias = wanted;
    for (let n = 2; seenAlias.has(alias); n++) alias = `${wanted.slice(0, 29)}-${n}`;
    seenLogin.add(login);
    seenAlias.add(alias);
    out.push({ login, email: login, alias });
  }
  return out;
}

/** Directory backed by a file (reloaded when its mtime changes) or by fixed lines (tests). */
export class MailboxDirectory {
  private cache: DirectoryEntry[] = [];
  private mtime = -1;

  private constructor(private readonly path: string | null, fixed?: DirectoryEntry[]) {
    if (fixed) this.cache = fixed;
  }

  static fromFile(path: string): MailboxDirectory {
    const d = new MailboxDirectory(path);
    d.entries(); // fail fast at boot when the file is unreadable
    return d;
  }

  static fromLines(lines: string[]): MailboxDirectory {
    return new MailboxDirectory(null, parseDirectory(lines.join('\n')));
  }

  entries(): DirectoryEntry[] {
    if (this.path) {
      const m = statSync(this.path).mtimeMs;
      if (m !== this.mtime) {
        this.cache = parseDirectory(readFileSync(this.path, 'utf8'));
        this.mtime = m;
      }
    }
    return this.cache;
  }

  get count(): number {
    return this.entries().length;
  }

  /**
   * Finds a mailbox by alias, by full login/address, or by bare domain (the `contact@` mailbox
   * of that domain when several exist). Case-insensitive.
   */
  resolve(key: string): DirectoryEntry | undefined {
    const k = key.trim().toLowerCase();
    if (!k) return undefined;
    const all = this.entries();
    return (
      all.find((e) => e.alias === k) ??
      all.find((e) => e.login === k || e.email === k) ??
      (k.includes('@') ? undefined : byDomain(all, k))
    );
  }
}

function byDomain(all: DirectoryEntry[], domain: string): DirectoryEntry | undefined {
  const hits = all.filter((e) => e.login.slice(e.login.lastIndexOf('@') + 1) === domain);
  if (hits.length === 1) return hits[0];
  return hits.find((e) => e.login.startsWith('contact@'));
}
